import{_ as t,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/plugins.md","filePath":"zh-CN/user-guide/settings/plugins.md","lastUpdated":1785993908000}'),n={name:"zh-CN/user-guide/settings/plugins.md"};function o(i,a,p,l,d,h){return e(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h1><p>列出所有已安装的插件，页面头部的徽标显示当前加载的 Plugin SDK 版本——点击它可以直接打开<a href="./../../dev-guide/">开发手册</a>，这个版本号正是为了对照手册开发插件而准备的。</p><p>页面分成左右两栏：左边是已安装的插件，右边是选中插件的详情。两栏各自独立滚动，插件列表很长和配置表单很长互不牵扯。</p><p>如果没有安装任何插件，页面会显示一个空状态提示。</p><h2 id="插件列表" tabindex="-1">插件列表 <a class="header-anchor" href="#插件列表" aria-label="Permalink to &quot;插件列表&quot;">​</a></h2><p>每个已安装的插件占一行，显示名称，下方是它的版本号。点击某一行，右侧就会打开该插件。</p><p>列表按&quot;有什么可操作的&quot;排序：先是有自己配置项的插件，其次是有组件可以关闭的，最后是其余的；每一档内部按名称排列。</p><h2 id="选中的插件" tabindex="-1">选中的插件 <a class="header-anchor" href="#选中的插件" aria-label="Permalink to &quot;选中的插件&quot;">​</a></h2><p>右栏最上方是插件的图标、名称和<strong>总体功能简介</strong>。</p><p>再往下，如果插件暴露了自己的配置项(超出简单启用/禁用的范畴)，会出现<strong>详情</strong>和<strong>配置</strong>两个标签页。没有任何配置项的插件不会显示标签栏——整栏就是它的详情。</p><h3 id="详情" tabindex="-1">详情 <a class="header-anchor" href="#详情" aria-label="Permalink to &quot;详情&quot;">​</a></h3><p>该插件注册的功能组件，按类型分组（搜索源、动态菜单提供者等）。每个可切换的组件都有自己的<strong>启用/禁用复选框</strong>；标记为必要项的组件会显示一个锁形图标，不能关闭。把鼠标悬停在组件旁边的 <strong>(!)</strong> 上，可以看到该组件的详细功能说明。</p><p>当某个分组（或整个插件）有 2 个及以上可切换组件时，标题旁会出现一个<strong>全选/全不选</strong>链接，点击即可一次性切换该范围内的所有复选框，不用逐个手动勾选。</p><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h3><p>插件自己的设置项，直接在这里编辑，不再另开对话框。如果插件把设置分成了 2 组及以上，这里还会有一行属于它自己的标签页，每组一个。</p><p>按下<strong>确定</strong>之前，什么都不会写入。离开这个标签页——切回详情，或者选择另一个插件——会把这些字段回滚到已保存的值，这样你放弃掉的修改就不会在之后被误提交。</p><p>想看插件配置实际长什么样、能改什么(比如改一个触发关键词)，可以参考<a href="./../instant-answers.html">即时答案与关键词功能</a>。</p>',17)])])}const c=t(n,[["render",o]]);export{g as __pageData,c as default};
